using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketClassifierService>();

// Train the model before building so the .zip file exists for the pool
var tempProvider = builder.Services.BuildServiceProvider();
var classifierService = tempProvider.GetRequiredService<TicketClassifierService>();
classifierService.TrainAndEvaluate();

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(classifierService.GetModelPath());

var app = builder.Build();
app.MapControllers();
app.Run();

